const g = $input.first().json;

// --- Перевірка ТО ---
const servicePct = Math.round(
  (g.hours_since_last_service / g.maintenance_interval_hours) * 100
);

let maintenanceAlert = null;

if (servicePct >= 100 && g.current_status !== 'critical') {
  maintenanceAlert = {
    type:    'maintenance_critical',
    message: `🔴 Генератор "${g.generator_name}" (${g.location_name}): ТО прострочено! ${g.hours_since_last_service} год з ${g.maintenance_interval_hours} год. Негайно виконайте обслуговування.`,
    new_status: 'critical'
  };
} else if (servicePct >= 80 && servicePct < 100 && g.current_status === 'ok') {
  maintenanceAlert = {
    type:    'maintenance_warning',
    message: `🟡 Генератор "${g.generator_name}" (${g.location_name}): наближається ТО. Відпрацьовано ${g.hours_since_last_service} год з ${g.maintenance_interval_hours} год (${servicePct}%).`,
    new_status: 'warning'
  };
}

// --- Перевірка палива ---
const fuelPct   = Math.round((g.current_fuel_litres / g.tank_volume_litres) * 100);
const hoursLeft = Math.round((g.current_fuel_litres / g.consumption_per_hour) * 10) / 10;

let fuelAlert = null;

const lastRefuel = g.last_refuel ? new Date(g.last_refuel) : null;

if (fuelPct <= 5) {
  const lastCriticalAlert = g.last_fuel_critical_alert ? new Date(g.last_fuel_critical_alert) : null;
  // Надсилаємо, якщо ніколи не надсилали АБО була заправка після останнього критичного алерта
  const shouldSendCritical = !lastCriticalAlert || (lastRefuel && lastRefuel > lastCriticalAlert);

  if (shouldSendCritical) {
    fuelAlert = {
      type:    'fuel_critical',
      message: `🔴 Генератор "${g.generator_name}" (${g.location_name}): КРИТИЧНО мало палива! Залишок: ${g.current_fuel_litres} л (${fuelPct}%). Роботи приблизно на ${hoursLeft} год.`
    };
  }
} else if (fuelPct <= 20) {
  const lastLowAlert = g.last_fuel_low_alert ? new Date(g.last_fuel_low_alert) : null;
  // Надсилаємо, якщо ніколи не надсилали АБО була заправка після останнього низького алерта
  const shouldSendLow = !lastLowAlert || (lastRefuel && lastRefuel > lastLowAlert);

  if (shouldSendLow) {
    fuelAlert = {
      type:    'fuel_low',
      message: `🟡 Генератор "${g.generator_name}" (${g.location_name}): мало палива. Залишок: ${g.current_fuel_litres} л (${fuelPct}%). Роботи приблизно на ${hoursLeft} год.`
    };
  }
}

return [{
  json: {
    generator_id:     g.generator_id,
    location_id:      g.location_id,
    company_id:       g.company_id,
    current_status:   g.current_status,
    maintenance_alert: maintenanceAlert,
    fuel_alert:        fuelAlert,
    has_any_alert:     !!(maintenanceAlert || fuelAlert)
  }
}];

const thresholds  = $('Calculate thresholds').item.json;
const recipients  = $input.all().map(r => r.json);

const alerts = [
  thresholds.maintenance_alert,
  thresholds.fuel_alert
].filter(Boolean);

const messages = [];

for (const recipient of recipients) {
  for (const alert of alerts) {
    messages.push({
      json: {
        telegram_id:  recipient.telegram_id,
        message:      alert.message,
        type:         alert.type,
        generator_id: thresholds.generator_id,
        location_id:  thresholds.location_id,
        company_id:   thresholds.company_id,
        new_status:   alert.new_status ?? null
      }
    });
  }
}

return messages;
